MAP
    NAME "SS_MAP_INFO_FISCALIZACION_ECOLOGICA_REJILLA_MEDIDOR"
    INCLUDE 'includes/globals.map'
    WEB
        INCLUDE "includes/temp_directory.map"
        METADATA
            INCLUDE 'includes/common_metadata.map'
            'wms_include_items' 'all'
            'gml_include_items' 'all'
            'wms_getfeatureinfo_formatlist' 'geojson'
        END #METADATA
    END #WEB
    CONFIG "MS_ERRORFILE" "/srv/mapserver/err_fiscalizacion_ecologica_rejilla_medidor.log"
    DEBUG 5
    # Se agrega formato de salida GEOJSON
    OUTPUTFORMAT
        NAME "geojson"
        MIMETYPE "application/json; subtype=geojson; charset=utf-8"
        FORMATOPTION "FORM=SIMPLE"
        FORMATOPTION "STORAGE=memory"
        FORMATOPTION "LCO:NATIVE_MEDIA_TYPE=application/vnd.geo+json"
        DRIVER "OGR/GEOJSON"
    END #OUTPUTFORMAT
    LAYER
        NAME "SS_MAP_INFO_FISCALIZACION_ECOLOGICA_REJILLA_MEDIDOR"
        PROJECTION
            'init=epsg:32614'
        END #PROJECTION
        CONNECTIONTYPE POSTGIS
        STATUS DEFAULT
        METADATA
            'gml_include_items' 'all'
            'wms_include_items' 'all'
            'wms_getfeatureinfo_formatlist' 'geojson'
            "wms_srs" "EPSG:32614 EPSG:4326"
        END #METADATA
        INCLUDE 'includes/conexion.map'
        #Se agrega alias de id_predio a id_elemento_geografico para alinear campo con servicio de ifentificar de Geomoose.
        PROCESSING "CLOSE_CONNECTION=DEFER"  # Reutiliza conexiones para múltiples consultas
        PROCESSING "POSTGIS_FILTER=YES"      # Filtra geometrías en el lado del servidor
        DATA "geometry from (select 'Rej. y Med: '||kefe.cl_rejilla_medidor as informacion, id_identificador_equipamiento, pc.npredio, kefe.cl_rejilla_medidor, p.geometry 
	    from predios_cuenta pc, k_equipamiento_fiscalizacion_ecologica kefe, predios p
	    where kefe.no_cuenta_comercial=pc.cuenta and pc.npredio = p.gid and kefe.cl_rejilla_medidor=1)as data using unique id_identificador_equipamiento using srid=32614"
        TYPE polygon
        LABELITEM "informacion"
        # ============= Rejillas-Medidor =============
        CLASS
            NAME "Rejilla y Medidor"
            LABEL	
                 TYPE TRUETYPE 
                 FONT 'arial'
                 SIZE 12
                 POSITION LL
                    OFFSET 0 10
                 COLOR 0 0 0
            END #LABEL
            STYLE
                COLOR 255 230 0
                WIDTH 5
                OUTLINECOLOR 114 148 200
            END #STYLE
        END #CLASS
    END #LAYER
END #MAP